def search_layer(q, ep, ef):
    visited = {ep}
    C = [ep]   # candidates, nearest first
    W = [ep]   # best ef found so far
    while C:
        c = pop_nearest(C)
        if dist(c, q) > dist(furthest(W), q):
            break  # nothing left can improve W
        for e in neighbors(c):
            if e in visited:
                continue
            visited.add(e)
            if len(W) < ef or dist(e, q) < dist(furthest(W), q):
                C.add(e)
                W.add(e)
                if len(W) > ef:
                    W.remove(furthest(W))
    return W

-- pgvector: HNSW index on a cosine-distance column
CREATE INDEX ON items USING hnsw (embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64);

-- query-time knob: beam width (default 40)
SET hnsw.ef_search = 100;

SELECT id FROM items
ORDER BY embedding <=> '[0.12, -0.03, ...]'
LIMIT 10;
